create table if not exists app.posts (id uuid primary key default gen_random_uuid(), owner_id uuid not null references app.profiles(id) on delete cascade, slug text not null, current_version_id uuid, status text not null default 'draft' check (status in ('draft','scheduled','published','archived')), scheduled_at timestamptz, published_at timestamptz, archived_at timestamptz, created_at timestamptz not null default now(), unique (owner_id, slug));
create table if not exists app.post_versions (id uuid primary key default gen_random_uuid(), post_id uuid not null references app.posts(id) on delete cascade, version integer not null, title text not null, markdown text not null, content_hash text not null, evidence_ids uuid[] not null default '{}', created_at timestamptz not null default now(), unique (post_id, version));
create table if not exists app.post_tags (post_id uuid not null references app.posts(id) on delete cascade, tag text not null, primary key (post_id, tag));
create table if not exists app.post_publication_approvals (id uuid primary key default gen_random_uuid(), post_id uuid not null references app.posts(id) on delete cascade, version_id uuid not null references app.post_versions(id), reviewer_id uuid not null references app.profiles(id), confirmed_at timestamptz not null default now());
alter table app.posts enable row level security;
create policy posts_owner on app.posts for all to authenticated using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));
